{"command": "create", "path": "/root/output/js/visualization.js", "file_text": "(function () {
    const CSV_PATH = "data/stock-descriptions.csv";

    function formatMarketCap(n) {
        if (n == null || isNaN(n) || n === 0) return "—";
        const units = [["T", 1e12], ["B", 1e9], ["M", 1e6], ["K", 1e3]];
        for (const [suffix, value] of units) {
            if (n >= value) return (n / value).toFixed(2) + suffix;
        }
        return n.toString();
    }

    const isETF = (d) => d.sector === "ETF" || !d.marketCap;

    d3.csv(CSV_PATH, (row) => ({
        ticker: row.ticker,
        sector: row.sector,
        name: row["full name"],
        marketCap: row.marketCap ? +row.marketCap : null,
        country: row.country || null,
        website: row.website || null,
    })).then(render);

    function render(data) {
        data.sort((a, b) => d3.ascending(a.sector, b.sector) || d3.ascending(a.ticker, b.ticker));

        const sectors = Array.from(new Set(data.map((d) => d.sector))).sort();
        const palette = [
            "#4E79A7", "#F28E2B", "#E15759", "#76B7B2",
            "#59A14F", "#EDC948", "#B07AA1", "#FF9DA7",
            "#9C755F", "#BAB0AC",
        ];
        const color = d3.scaleOrdinal().domain(sectors).range(palette);

        const svgEl = document.getElementById("chart");
        const rect = svgEl.getBoundingClientRect();
        const width = Math.max(500, rect.width);
        const height = Math.max(500, rect.height);

        const svg = d3.select("#chart")
            .attr("viewBox", `0 0 ${width} ${height}`)
            .attr("preserveAspectRatio", "xMidYMid meet");

        const stockCaps = data.filter((d) => !isETF(d)).map((d) => d.marketCap);
        const capExtent = d3.extent(stockCaps);
        const rScale = d3.scaleSqrt()
            .domain([capExtent[0], capExtent[1]])
            .range([18, 55]);
        const etfRadius = 28;

        data.forEach((d) => {
            d.radius = isETF(d) ? etfRadius : rScale(d.marketCap);
        });

        // Sector cluster centers arranged near the middle of the SVG.
        const centers = computeSectorCenters(sectors, width, height);

        const simulation = d3.forceSimulation(data)
            .force("x", d3.forceX((d) => centers[d.sector].x).strength(0.18))
            .force("y", d3.forceY((d) => centers[d.sector].y).strength(0.18))
            .force("center", d3.forceCenter(width / 2, height / 2).strength(0.02))
            .force("collide", d3.forceCollide((d) => d.radius + 2).strength(1))
            .stop();

        data.forEach((d) => {
            const c = centers[d.sector];
            d.x = c.x + (Math.random() - 0.5) * 20;
            d.y = c.y + (Math.random() - 0.5) * 20;
        });
        for (let i = 0; i < 300; i++) simulation.tick();

        const bubbles = svg.append("g")
            .selectAll("g.bubble")
            .data(data, (d) => d.ticker)
            .join("g")
            .attr("class", "bubble")
            .attr("data-ticker", (d) => d.ticker)
            .attr("transform", (d) => `translate(${d.x},${d.y})`);

        bubbles.append("circle")
            .attr("r", (d) => d.radius)
            .attr("fill", (d) => color(d.sector));

        bubbles.append("text")
            .attr("font-size", (d) => Math.max(9, Math.min(16, d.radius * 0.55)))
            .text((d) => d.ticker);

        renderLegend(sectors, color);

        const tooltip = d3.select("#tooltip");
        bubbles
            .on("mouseover", function (event, d) {
                if (isETF(d)) return;
                tooltip.classed("visible", true).html(
                    `<div class="t-ticker">${d.ticker}</div>` +
                    `<div>${escapeHtml(d.name)}</div>` +
                    `<div>Sector: ${escapeHtml(d.sector)}</div>`
                );
                positionTooltip(event);
            })
            .on("mousemove", function (event, d) {
                if (isETF(d)) return;
                positionTooltip(event);
            })
            .on("mouseout", function () {
                tooltip.classed("visible", false);
            })
            .on("click", function (event, d) {
                selectTicker(d.ticker);
            });

        const tbody = d3.select("#stock-table tbody");
        const rows = tbody.selectAll("tr")
            .data(data, (d) => d.ticker)
            .join("tr")
            .attr("data-ticker", (d) => d.ticker)
            .on("click", function (event, d) {
                selectTicker(d.ticker);
            });

        rows.append("td").text((d) => d.ticker);
        rows.append("td").text((d) => d.name);
        rows.append("td").text((d) => d.sector);
        rows.append("td").text((d) => isETF(d) ? "—" : formatMarketCap(d.marketCap));

        let selected = null;
        function selectTicker(ticker) {
            selected = selected === ticker ? null : ticker;
            svg.selectAll("g.bubble")
                .classed("selected", (d) => d.ticker === selected);
            tbody.selectAll("tr")
                .classed("selected", (d) => d.ticker === selected);
            if (selected) {
                const el = tbody.selectAll("tr").filter((d) => d.ticker === selected).node();
                if (el && el.scrollIntoView) el.scrollIntoView({ block: "nearest", behavior: "smooth" });
            }
        }

        function positionTooltip(event) {
            tooltip
                .style("left", (event.pageX + 14) + "px")
                .style("top", (event.pageY - 10) + "px");
        }
    }

    function computeSectorCenters(sectors, width, height) {
        const n = sectors.length;
        const cx = width / 2;
        const cy = height / 2;
        // Radius of the ring on which cluster centers sit — well inside the viewport.
        const ringR = Math.min(width, height) * 0.22;
        const centers = {};
        sectors.forEach((s, i) => {
            const angle = (i / n) * Math.PI * 2 - Math.PI / 2;
            centers[s] = {
                x: cx + ringR * Math.cos(angle),
                y: cy + ringR * Math.sin(angle),
            };
        });
        return centers;
    }

    function renderLegend(sectors, color) {
        const legend = d3.select("#legend");
        legend.selectAll("*").remove();
        legend.append("div")
            .style("font-weight", "600")
            .style("margin-bottom", "4px")
            .text("Sector");
        const items = legend.selectAll("div.legend-item")
            .data(sectors)
            .join("div")
            .attr("class", "legend-item");
        items.append("span")
            .attr("class", "legend-swatch")
            .style("background", (d) => color(d));
        items.append("span").text((d) => d);
    }

    function escapeHtml(s) {
        if (s == null) return "";
        return String(s)
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#39;");
    }
})();
