        const capExtent = d3.extent(stockCaps);
        const rScale = d3.scaleSqrt()
            .domain([capExtent[0], capExtent[1]])
            .range([18, 55]);
        const etfRadius = 28;

        data.forEach((d) => {
            d.radius = isETF(d) ? etfRadius : rScale(d.marketCap);
        });

